        "analogy": "يشبه مفهوم (ما هو عنوان IP؟) نظام التعامل في مكاتب البريد الكبرى؛ حيث يتم وضع الرسالة في مظروف قياسي محدد، وتدوين عنوان الراسل وعنوان المرسل إليه ورقم الصندوق بدقة لضمان وصول الطرد إلى وجهته الصحيحة دون ضياع أو تداخل.",
